INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Първи дентален преглед и цялостно планиране на лечението',
'<p>Цялостният първи преглед представлява изслушване на оплакването, снемане на медицинска и дентална анамнеза, клинична оценка на устната кухина и околните тъкани и съвместно тълкуване само на онези записи, които са преценени като необходими. Планът на лечение се изгражда поетапно въз основа на тези находки, приоритетите на пациента и подходящите възможности.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="Изслушване на причината за посещението и очакванията на пациента при първия преглед" loading="lazy"  /></p>
<h2>Причина за посещението и очаквания</h2>
<p>Болка, естетични очаквания, затруднено дъвчене, липсващи зъби, налични възстановявания и приоритети се записват със собствените думи на пациента. Първата цел не е да се избере процедура, а да се разберат нуждите и критериите за решение.</p>
<h2>Медицинска и дентална анамнеза</h2>
<p>Разпитва се за общи заболявания, алергии, възможна бременност, предишни операции и лечения, приемани лекарства и минали дентални преживявания. При нужда се взема становището на лекуващия лекар; пациентът не спира лекарствата си по собствено решение. За планирането на лечението при бременност вижте страницата <a href="/bg/hamilelikte-dis-tedavisi/">Дентално лечение при бременност</a>.</p>
<h2>Екстраорален преглед и преглед на меките тъкани</h2>
<p>Систематично се оценяват симетрията на лицето, движенията на челюстта, лимфните възли и необходимите екстраорални находки, както и меките тъкани — устни, бузи, език, небце и под на устната кухина. При установяване на съмнителна находка се планират разширена оценка и необходимите изследвания.</p>
<h2>Зъби и налични възстановявания</h2>
<p>По клиничните находки се оценяват съмнение за <a href="/bg/dis-curugu-kompozit-dolgu/">кариес</a>, фрактури и износвания, промени в цвета, чувствителност, подвижност на зъбите, състоянието на обтурациите, короните и мостовете, както и зоните с липсващи зъби. При нужда се добавят тестове за виталност и други помощни изследвания.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="Систематичен преглед на зъбите, венците и тъканите на устната кухина" loading="lazy"  /></p>
<h2>Оценка на венците и пародонта</h2>
<p>Оценяват се плаката и зъбният камък, кървенето, рецесията на венците, дълбочината на джобовете, поддържащите тъкани и рисковите показатели. Здравето на венците може да промени реда на лечение преди имплантологични, протетични или естетични процедури.</p>
<h2>Как се използват заедно данните от прегледа?</h2>
<table>
<thead><tr><th>Запис</th><th>Принос</th><th>Принцип на използване</th></tr></thead>
<tbody>
<tr><td>Клиничен преглед</td><td>Находки за зъбите, венците, меките тъкани, ставата и оклузията</td><td>Базова оценка, чийто обхват при всеки пациент се определя според нуждата</td></tr>
<tr><td>Рентгенов запис</td><td>Оценка на невидимите с око корени, кост и апроксимални повърхности</td><td>Само изображението, което е необходимо според анамнезата, предишните записи и клиничната находка</td></tr>
<tr><td>Снимки / дигитален скан</td><td>Запис, който помага да се документират изходното състояние, зъбната редица и оклузията</td><td>Според вида лечение и нуждите на планирането; сам по себе си не е категорична диагноза</td></tr>
</tbody>
</table>
<p><strong>Важно:</strong> панорамна снимка, томография, фотографии или дигитален скан не са автоматичен пакет за всеки пациент. Оценяват се давността и диагностичната стойност на предишните записи; нов запис се прави само при клинична необходимост.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="Съвместна оценка на клиничните, рентгеновите и дигиталните записи" loading="lazy"  /></p>
<h2>Оклузия, става и функция</h2>
<p>Оценяват се контактите между зъбите, дъвкателните отношения, отварянето на устата, оплакванията от ставата и мускулите, стискането и скърцането, както и находките от износване. Всеки звук или износване сам по себе си не означава заболяване или нужда от шина.</p>
<h2>Избор на образен метод</h2>
<p>Байтуинг, периапикална, панорамна снимка или триизмерна образна диагностика се избират според находките от прегледа и планираната процедура. Подход с томография при всеки пациент не се прилага; очакваният диагностичен принос се съпоставя с лъчевото натоварване.</p>
<h2>Ролята на дигиталните записи</h2>
<p>Записите от интраорален скенер, стандартните снимки и дигиталните модели могат да помогнат за документиране на изходното състояние, оклузията и възстановителния план. Резултатът от софтуера не замества прегледа от лекар и клиничната проверка.</p>
<h2>Диагноза и оценка на риска</h2>
<p>Заедно се разглеждат кариесът, заболяването на венците, проблемите с пулпата и периапикалните тъкани, рискът от фрактура, хигиената, тютюнопушенето, храненето и навиците за грижа. За находки, които не могат да бъдат уточнени, може да се планира наблюдение или допълнително изследване.</p>
<h2>Поетапен план на лечение</h2>
<ol>
<li>Овладяване на спешната болка и инфекцията</li>
<li>Спиране на заболяването и базово здраве на венците</li>
<li>Окончателни възстановителни, хирургични или протетични етапи</li>
<li>Грижа и индивидуално определен интервал на прегледи</li>
</ol>
<p>Клиничното състояние може да промени този ред. Какво съдържа планът и как се актуализира, вижте на страницата <a href="/bg/tedavi-plani-ve-surec/">План на лечение и ход</a>.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="Обясняване на поетапния план на лечение на пациента" loading="lazy"  /></p>
<h2>Възможности и ход</h2>
<p>По разбираем начин се обсъждат целта на всяка приложима възможност, съществените ѝ ползи и рискове, алтернативите, възможните последици от липса на лечение, както и приблизителните срок и обхват. Планът може да се актуализира според нови клинични находки или отговора на зарастването. Информираното съгласие не е само подпис; то е процес на разбираемо информиране и възможност да се задават въпроси.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Прави ли се лечение още при първия преглед?</strong><br>Не винаги. Приоритет са оценката и безопасното планиране. Спешна болка или подходяща проста процедура могат да се направят в същия ден, ако има време и съгласие. Цялостното лечение най-често започва след планирането.</p>
<p><strong>От всеки пациент ли се изисква панорамна снимка?</strong><br>Не. Видът и моментът на образната диагностика се определят според анамнезата, клиничния преглед, предишните снимки и планираната процедура. Ако наличните записи са достатъчни, не се правят излишни повторения.</p>
<p><strong>Как се определя приоритетът в плана на лечение?</strong><br>Първо идват спешните състояния и овладяването на инфекцията; след завършване на базовите етапи като контрол на венците и кариеса се планират окончателните възстановявания, имплантите и протетиката или естетичните процедури.</p>
<p><strong>Мога ли да донеса наличните си записи за второ мнение?</strong><br>Да. Рентгеновите снимки, заключенията, информацията за импланти и записите от предишно лечение могат да помогнат при оценката. Ако обаче давността или качеството на изображението са недостатъчни, може да се наложи допълнителен запис.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт първият преглед се разглежда като цялостен процес на планиране, при който заедно се оценяват оплакването, медицинската анамнеза, здравето на зъбите и венците, оклузията и само необходимите клинични и дигитални записи.</p>
<p><a href="/bg/acil-dis-agrisinda-ilk-24-saat/">Спешна зъбна болка</a> &middot; <a href="/bg/tedavi-plani-ve-surec/">План на лечение и ход</a> &middot; <a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> &middot; <a href="/bg/iletisim">Час и контакти</a></p>',
'Научете за медицинската анамнеза, оценката на венците и оклузията, необходимите рентгенови снимки, дигиталните записи и поетапния план на лечение при първия дентален преглед.',
'Първи дентален преглед и план на лечение | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'ilk-dis-muayenesi-tedavi-planlamasi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'План на лечение и прозрачност на процеса: какво определя обхвата?',
'<p>При денталното лечение несигурността често създава повече тревога от самото лечение. Когато след прегледа писмено се съобщава кои процедури ще се извършат, в колко етапа ще приключат и в какъв ред ще протекат, пациентът взема решението си информирано. Тази страница обяснява как протича процесът още преди посещението в клиниката.</p>
<p><img src="/assets/uploads/images/ts90-01-tedavi-plani-gorusmesi.webp" alt="Лекарят обсъжда плана на лечение с пациента" loading="lazy"  /></p>
<h2>Какво съдържа планът на лечение?</h2>
<table>
<thead><tr><th>Раздел</th><th>Описание</th></tr></thead>
<tbody>
<tr><td>Клинични находки</td><td>Състоянието, установено след прегледа и необходимата образна диагностика.</td></tr>
<tr><td>Предложени процедури</td><td>Коя процедура се предлага за кой зъб, по разбираем начин.</td></tr>
<tr><td>Алтернативи</td><td>Други подходи, които могат да се обсъждат при същия проблем, и разликите между тях.</td></tr>
<tr><td>Етапи и ред</td><td>Коя процедура трябва да се направи първа и защо.</td></tr>
<tr><td>Приблизителен ход</td><td>Приблизителен брой посещения и очаквани периоди на изчакване за зарастване.</td></tr>
<tr><td>Какво става, ако не се направи?</td><td>Очакваният ход при отлагане на лечението.</td></tr>
<tr><td>Нужди от грижа</td><td>Очаквания за контролни прегледи и ежедневна грижа след лечението.</td></tr>
</tbody>
</table>
<p>При цялостните планове тази информация се предоставя и писмено наред с устното обяснение; пациентът има време да помисли и да зададе въпросите си.</p>
<h2>Какво определя обхвата на плана?</h2>
<p>Планът на лечение на двама души с едно и също оплакване може да не е еднакъв. Основните фактори, определящи обхвата:</p>
<ul>
<li>Видът на проблема, разпространението му и степента на напредване</li>
<li>Оставащата здрава зъбна тъкан и състоянието на венечната и костната опора</li>
<li>Оклузалните отношения, навикът за стискане и скърцане</li>
<li>Общото здравословно състояние, приеманите лекарства, тютюнопушенето</li>
<li>Навиците за орална хигиена и възможността за явяване на прегледи</li>
<li>Избраният метод, използваният материал и лабораторният етап</li>
<li>Нуждата от подготвителни процедури (лечение на венците, увеличаване на костта, ортодонтска подготовка и др.)</li>
</ul>
<p>Без преглед план не може да се изготви. Категорична информация за лечението и обхвата му, дадена по телефон, съобщение или по снимка, не е надеждна. Предварителният разговор дава само обща представа; планът се изготвя след клиничен преглед и необходимата образна диагностика.</p>
<p><img src="/assets/uploads/images/ts90-03-muayene-ve-degerlendirme.webp" alt="Съвместно извършване на преглед и рентгенова оценка" loading="lazy"  /></p>
<h2>Поетапно планиране и ред на приоритетите</h2>
<p>При цялостните лечения не всичко се прави едновременно. Обикновено се следва този ред:</p>
<table>
<thead><tr><th>Етап</th><th>Съдържание</th></tr></thead>
<tbody>
<tr><td>1 — Спешен</td><td>Състояния, които не търпят отлагане: болка, инфекция, оток и травма.</td></tr>
<tr><td>2 — Спиране на заболяването</td><td><a href="/bg/dis-curugu-kompozit-dolgu/">Лечение на кариеса</a>, лечение на венците, подреждане на оралната хигиена.</td></tr>
<tr><td>3 — Възстановяване</td><td>Обтурации, корони, <a href="/bg/kanal-tedavisi/">кореново лечение</a>, <a href="/bg/dental-implant-tedavisi/">възстановяване на липсващи зъби</a>.</td></tr>
<tr><td>4 — Естетика</td><td>Незадължителни естетични процедури; след решаване на здравословните проблеми.</td></tr>
<tr><td>5 — Профилактика и проследяване</td><td>Редовни прегледи, почистване, при нужда нощна шина.</td></tr>
</tbody>
</table>
<p>Този ред цели основата, върху която се изгражда работата, да бъде стабилна. Дългосрочният резултат на естетично възстановяване, направено при продължаващо възпаление на венците, може да пострада.</p>
<p><img src="/assets/uploads/images/ts90-02-asamali-planlama.webp" alt="Схема, показваща разделянето на плана на лечение на етапи" loading="lazy"  /></p>
<h2>Може ли планът да се промени?</h2>
<p>Да. В денталната медицина някои находки се виждат само по време на процедурата: например дълбочината на кариеса се изяснява точно при почистването и може да възникне нужда от кореново лечение. В такива случаи преди продължаването пациентът се информира и се взема съгласието му. Актуализирането на плана не означава, че първоначалната оценка е била погрешна.</p>
<h2>Общественото осигуряване (SGK) и денталното лечение</h2>
<p>Правата за дентално лечение в обхвата на Институцията за обществено осигуряване се различават според вида на заведението, към което се обръщате. Услугите по орално и дентално здраве се предоставят в държавните здравни заведения и в заведенията с договор с SGK, в рамките, определени в нормативната уредба.</p>
<p><strong>Нашата клиника няма договор с Институцията за обществено осигуряване.</strong> Тази информация е посочена тук изрично, тъй като трябва да е известна преди запазването на час. При промяна в нормативната уредба или в договорния статус този раздел ще бъде актуализиран.</p>
<h2>Въпроси, които можете да зададете на лекаря</h2>
<ul>
<li>Кои процедури се предлагат в моя случай и защо?</li>
<li>Какви са алтернативите на това лечение? Каква е разликата между тях?</li>
<li>Кое трябва да се направи сега и кое може да почака?</li>
<li>Колко посещения се очакват? Какъв ще е интервалът между тях?</li>
<li>Какво е нормално да усещам след процедурата и в какъв случай да Ви потърся?</li>
<li>Какво ще стане, ако не направя това лечение?</li>
<li>Какъв режим на грижа и прегледи е необходим след това?</li>
<li>Мога ли да получа информация за използвания материал?</li>
<li>Как ще бъда информиран, ако планът се промени по време на лечението?</li>
</ul>
<h2>Вашите лични данни</h2>
<p>Информацията, получена при прегледа, образната диагностика и лечението, е лични данни от специална категория. С каква цел се обработва, колко дълго се съхранява и какви права имате, е обяснено в <a href="/bg/sayfa/kvkk-aydinlatma-metni">информацията за защита на личните данни</a>. Чрез формуляра за час не се изискват подробни здравни данни или изображения; при нужда безопасният начин се съобщава отделно.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Мога ли да разбера обхвата на лечението по телефона?</strong><br>Тъй като обхватът на лечението не може да се определи без преглед, по телефона не се дава категорична информация. След прегледа индивидуалният план се предоставя писмено.</p>
<p><strong>Мога ли да взема време да обмисля плана на лечение?</strong><br>Да. Ако няма спешно състояние, е естествено да отделите време за преценка на плана. Въпросите си можете да зададете и по-късно.</p>
<p><strong>Мога ли да поискам мнението на друг лекар?</strong><br>Да. Получаването на второ мнение е право на пациента. По Ваше желание наличните записи могат да бъдат предоставени.</p>
<p><strong>Какво става, ако планът се промени по време на лечението?</strong><br>Преди продължаването ситуацията се обяснява, представят се възможностите и се взема Вашето съгласие.</p>
<p><strong>Какво да донеса на часа?</strong><br>Документ за самоличност, налични предишни рентгенови снимки и записи от лечение, списък на приеманите лекарства и информация за известни заболявания или алергии. Ако имате заключение от друг лекар, носете го със себе си.</p>
<p><strong>Мога ли да получа фактура и документи?</strong><br>За извършените процедури се изготвя документация съгласно нормативната уредба. По Ваше желание се издава копие от записите за лечението Ви.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт планът на лечение се изготвя чрез съвместна оценка на клиничния преглед, необходимата образна диагностика и очакванията на пациента и се споделя с него.</p>
<p><a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> &middot; <a href="/bg/kanal-tedavisi/">Кореново лечение</a> &middot; <a href="/bg/sayfa/kvkk-aydinlatma-metni">Защита на личните данни</a> &middot; <a href="/bg/iletisim">Час и контакти</a></p>',
'Какво съдържа планът на лечение и какво определя обхвата му? Какво да знаете преди часа и какви въпроси да зададете.',
'План на лечение и прозрачност на процеса | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'tedavi-plani-ve-surec';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Какво да правите в първите 24 часа при спешна зъбна болка?',
'<p><strong>Боли ли Ви в момента?</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Как да стигнете</a></p>
<p>Силната зъбна болка най-често не преминава от само себе си; намаляването ѝ не означава, че проблемът е изчезнал. Целта в първите 24 часа е болката да се овладее безопасно и възможно най-скоро да се запази час за оценка. Препоръките по-долу са с информационна цел и не заместват прегледа.</p>
<h2>Какво може да се направи веднага</h2>
<ul>
<li>Устата може да се изплакне внимателно с хладка вода.</li>
<li>Ако в болезнената област е заседнала храна, може внимателно да се опита почистване с конец за зъби.</li>
<li>Студен компрес отвън върху бузата (лед, увит в кърпа, през интервали от 10–15 минути) може да помогне за намаляване на отока и болката.</li>
<li>Спането с леко повдигната глава може да облекчи, особено при пулсираща болка, която се засилва през нощта.</li>
<li>Ако се обмисля обезболяващо, изберете лекарство, което преди това е било препоръчано от лекар или фармацевт и няма пречки да го използвате, без да надвишавате дозата на опаковката.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-05-soguk-uygulama.webp" alt="Поставяне на студен компрес, увит в кърпа, отвън върху бузата при зъбобол" loading="lazy"  /></p>
<h2>Какво да се избягва</h2>
<ul>
<li><strong>Не използвайте антибиотик без рецепта.</strong> Антибиотикът не премахва източника на болката; временно маскира картината, затруднява диагнозата, а ненужната употреба допринася за развитие на резистентност.</li>
<li>Не поставяйте върху болния зъб или венец аспирин, обезболяващи таблетки, одеколон, алкохол или оцет; те могат да причинят химическо изгаряне на венеца.</li>
<li>При оток не прилагайте топлина; топлият компрес може да улесни разпространението на възпалението.</li>
<li>Не се опитвайте сами да пробиете или изстискате абсцес.</li>
<li>Не дъвчете твърда храна от болната страна.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-06-kacinilmasi-gerekenler.webp" alt="Лекарства без рецепта и топъл компрес, които трябва да се избягват при зъбобол" loading="lazy"  /></p>
<h2>Признаци, изискващи незабавно посещение</h2>
<p>Ако е налице някой от следните признаци, картината не е само зъбен проблем; трябва без забавяне да се отиде в <strong>най-близкото спешно отделение</strong>. Не бива да се чака час в денталния кабинет.</p>
<table>
<thead><tr><th>Признак</th><th>Защо е спешно?</th></tr></thead>
<tbody>
<tr><td>Затруднено дишане или преглъщане</td><td>Отокът може да стеснява дихателните пътища. Това е животозастрашаващо и трябва да се позвъни директно на спешния номер.</td></tr>
<tr><td>Разпространяващ се оток по пода на устата или шията</td><td>Може да показва напредване на инфекцията към дълбоките шийни пространства.</td></tr>
<tr><td>Оток, разпространяващ се около окото, затварящ се клепач</td><td>Може да сочи напредване нагоре на инфекция с произход от горната челюст.</td></tr>
<tr><td>Висока температура, втрисане, отпадналост</td><td>Може да показва, че инфекцията е преминала местните граници.</td></tr>
<tr><td>Невъзможност устата да се отвори (тризмус)</td><td>Може да показва засягане на дъвкателните мускули и разпространение на инфекцията.</td></tr>
<tr><td>Кървене, което не спира</td><td>Изисква спешна оценка, особено при приемащите кръворазреждащи лекарства.</td></tr>
</tbody>
</table>
<p><strong>При счупване на зъб или изваждането му вследствие на удар:</strong> дръжте зъба за короната, не търкайте корена; съхранявайте го в мляко, физиологичен разтвор или слюнка и потърсете помощ възможно най-скоро. Времето тук е решаващо. За подробни указания при деца вижте страницата <a href="/bg/cocuklarda-dis-travmasi/">Дентални травми при деца</a>.</p>
<h2>Какво се прави в клиниката?</h2>
<p><img src="/assets/uploads/images/ts83-01-acil-degerlendirme-gorusmesi.webp" alt="Оценка на пациента от лекаря при посещение със спешна зъбна болка" loading="lazy"  /></p>
<table>
<thead><tr><th>Стъпка</th><th>Какво се прави</th><th>Какво се очаква</th></tr></thead>
<tbody>
<tr><td>Бърза оценка</td><td>Разпитва се за мястото, продължителността, вида и провокиращите фактори на болката</td><td>Определяне дали е нужна спешна намеса</td></tr>
<tr><td>Клиничен преглед</td><td>Изследват се зъбът, венецът и околните тъкани; може да се направи тест за виталност</td><td>Определяне на източника на болката</td></tr>
<tr><td>Рентгеново изследване</td><td>При нужда се прави периапикална или панорамна снимка</td><td>Визуализиране на състоянието на корена и костта</td></tr>
<tr><td>Премахване на болката</td><td>Според случая се прави дренаж, <a href="/bg/kanal-tedavisi/">отваряне на канала</a> или временно възстановяване</td><td>Овладяване на болката</td></tr>
<tr><td>Представяне на плана</td><td>Обясняват се възможностите за окончателно лечение и графикът</td><td>Писмена информация за следващите стъпки</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts83-02-panoramik-rontgen-incelemesi.webp" alt="Анализ на панорамна снимка за определяне на източника на зъбобола" loading="lazy"  /></p>
<p>При спешните посещения приоритет са премахването на болката и овладяването на инфекцията. Окончателното лечение обикновено се планира на следващите посещения, след утихване на острата картина; за подробности вижте страницата <a href="/bg/tedavi-plani-ve-surec/">План на лечение и ход</a>.</p>
<p><img src="/assets/uploads/images/ts83-03-brosurle-bilgilendirme.webp" alt="Обясняване на пациента на възможностите за лечение чрез брошура" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts83-04-takip-ve-kontrol-plani.webp" alt="Представяне на пациента на плана за контрол и проследяване след лечението" loading="lazy"  /></p>
<h2>Достъп и час</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт се приемат спешни посещения; това важи и за пациентите ни от Бююкчекмедже и съседните райони. Свързването с нас по телефон или WhatsApp преди идване е важно както за подготовката на реда, така и за указанията какво да правите по пътя.</p>
<p><strong>Извън работно време:</strong> нашият дежурен лекар прави първата оценка при посещения извън работно време и спешни случаи и започва лечението. Ако са налице посочените по-горе спешни признаци, не бива да се чака, а да се отиде в най-близкото спешно отделение.</p>
<p><a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Как да стигнете</a></p>
<h2>Често задавани въпроси</h2>
<p><strong>Взех обезболяващо и болката премина, да дойда ли все пак?</strong><br>Да. Обезболяващото само потиска сигнала за болка, но не премахва състоянието, което я причинява. Особено когато е засегнат зъбният нерв, болката може за известно време да отслабне, а после да се върне по-силна. Препоръчва се да си запазите час за оценка.</p>
<p><strong>Ако започна антибиотик, ще премине ли болката?</strong><br>Антибиотик може да бъде предписан от лекар като допълнение към лечението при някои инфекции, но сам по себе си не е решение и не бива да се започва самостоятелно. Източникът на болката най-често се премахва с механична намеса (отваряне на канала, дренаж). Ненужната употреба на антибиотици и затруднява диагнозата, и допринася за антибиотичната резистентност.</p>
<p><strong>При зъбобол, започнал през нощта, да чакам ли до сутринта?</strong><br>Ако болката може да се контролира с лекарство и няма посочените спешни признаци, може да си запазите час сутринта. Но при оток, температура, затруднено преглъщане или дишане не бива да се чака до сутринта, а да се отиде в най-близкото спешно отделение.</p>
<p><strong>Болката премина, но на венеца има малко мехурче, важно ли е?</strong><br>Това мехурче може да показва, че възпалението си е намерило изход. Намаляването на болката не означава оздравяване; процесът може да продължи тихо. Препоръчва се да си запазите час за оценка.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт приоритет при спешните посещения е безопасното премахване на болката и овладяването на инфекцията. Окончателният план на лечение се изготвя заедно с пациента след утихване на острата картина.</p>
<p><a href="/bg/agiz-dis-sagligi/">Орално и дентално здраве</a> &middot; <a href="/bg/kanal-tedavisi/">Кореново лечение</a> &middot; <a href="/bg/dis-curugu-kompozit-dolgu/">Кариес и композитна обтурация</a> &middot; <a href="/bg/iletisim">Час и контакти</a></p>',
'Какво да правите в първите 24 часа при силна зъбна болка, какво да избягвате и при кои признаци да потърсите помощ без забавяне? Стъпка по стъпка спешно ръководство.',
'Спешна зъбна болка: първите 24 часа | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'acil-dis-agrisinda-ilk-24-saat';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Дентално лечение при бременност: безопасно ли е и кога да се направи?',
'<p>По време на бременност преглед, отстраняване на зъбен камък, обтурации, кореново лечение и необходима екстракция могат да се извършват при подходящи предпазни мерки. Състояния като болка, оток или инфекция не бива да се отлагат; нелекуваната инфекция може да представлява по-голям риск както за майката, така и за бебето. Незадължителните естетични процедури обикновено се оставят за след раждането. Важно е при всеки час да съобщавате за бременността и нейната седмица.</p>
<h2>Какво се променя в устата при бременност?</h2>
<table>
<thead><tr><th>Промяна</th><th>Описание</th></tr></thead>
<tbody>
<tr><td>Гингивит на бременността</td><td>Хормоналните промени правят венеца по-чувствителен към плаката; често се наблюдават зачервяване, оток и кървене при четкане.</td></tr>
<tr><td>Подутина на венеца</td><td>При някои жени на венеца може да се образува лесно кървяща доброкачествена червена подутина. Най-често намалява след раждането; въпреки това трябва да бъде оценена от лекар.</td></tr>
<tr><td>Повишен риск от кариес</td><td>Честото похапване, гаденето и повръщането повишават контакта с киселини и нарушават хигиената, което може да увеличи риска от кариес.</td></tr>
<tr><td>Ерозия на емайла</td><td>Повтарящото се повръщане може да доведе до киселинна ерозия на зъбните повърхности.</td></tr>
</tbody>
</table>
<p>Има проучвания, които съобщават за връзка между заболяването на венците при бъдещи майки и преждевременното раждане; не е доказано обаче със сигурност, че лечението на венците по време на бременност предотвратява преждевременното раждане. Лечението на венците е важно за оралното здраве на майката и трябва да се прави с тази цел.</p>
<h2>Планиране по периоди</h2>
<table>
<thead><tr><th>Период</th><th>Общ подход</th></tr></thead>
<tbody>
<tr><td>Първи триместър (1.–13. седмица)</td><td>Преглед и почистване могат да се правят. Тъй като гаденето може да е силно, дългите процедури, ако не са спешни, могат да се планират за следващия период. Спешните състояния не се отлагат.</td></tr>
<tr><td>Втори триместър (14.–27. седмица)</td><td>За много бъдещи майки това е най-комфортният период. Необходимите обтурации, <a href="/bg/kanal-tedavisi/">кореновото лечение</a> и лечението на венците най-често се планират тогава.</td></tr>
<tr><td>Трети триместър (след 28. седмица)</td><td>Необходимите лечения могат да се правят; тъй като обаче продължителното лежане по гръб може да причини дискомфорт и спад на кръвното налягане, часовете се планират кратки и се следи положението на тялото.</td></tr>
</tbody>
</table>
<p>Това е обща рамка; планът се определя индивидуално според хода на бременността и препоръките на Вашия акушер-гинеколог.</p>
<h2>На какво се обръща внимание в клиниката?</h2>
<p><img src="/assets/uploads/images/ts79-01-unit-pozisyonu.webp" alt="Бременна пациентка в денталния стол, с опора и леко завъртяна наляво" loading="lazy" /></p>
<table>
<thead><tr><th>Тема</th><th>Описание</th></tr></thead>
<tbody>
<tr><td>Информиране</td><td>Трябва да се съобщят седмицата на бременността, приеманите витамини и лекарства, евентуална рискова бременност и препоръките на Вашия акушер-гинеколог.</td></tr>
<tr><td>Местна упойка</td><td>Местните упойки, използвани в денталното лечение, могат да се прилагат по време на бременност в дози, които лекарят прецени за подходящи. Лечението с болка може да създаде повече стрес от използването на упойка.</td></tr>
<tr><td>Рентген</td><td>Прави се само ако е наистина необходим за диагнозата. Лъчевата доза при денталните снимки е много ниска и те се правят със защитни мерки.</td></tr>
<tr><td>Лекарства</td><td>Ако е нужно обезболяващо или антибиотик, се избират възможности, считани за безопасни при бременност, при нужда със становището на Вашия акушер-гинеколог. Не приемайте лекарства по собствено решение.</td></tr>
<tr><td>Положение</td><td>В напреднала бременност полуседнало положение със завъртане наляво е по-удобно от пълното лежане по гръб. При световъртеж, гадене или задух веднага кажете на лекаря.</td></tr>
<tr><td>Продължителност на часа</td><td>Предпочитат се кратки часове с чести почивки.</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts79-02-gebelik-bilgisi-paylasimi.webp" alt="Бременна пациентка съобщава на зъболекаря информация за бременността и здравето си" loading="lazy" /></p>
<h2>Грижа у дома и гадене</h2>
<p><img src="/assets/uploads/images/ts79-03-bulanti-sonrasi-calkalama.webp" alt="Изплакване на устата с вода след гадене по време на бременност" loading="lazy" /></p>
<p>Препоръчва се четкане два пъти дневно с флуоридна паста и мека четка и ежедневно почистване между зъбите. Не спирайте четкането заради кървене на венците; кървенето най-често е признак за натрупване на плака и намалява при редовно и внимателно почистване.</p>
<p>След повръщане вместо да четкате веднага, изплакнете устата с вода и изчакайте известно време; омекналата от киселина повърхност на емайла се изтрива по-лесно с четка. Ако четкането предизвиква гадене, опитайте четка с малка глава и паста с по-слаб аромат. Ако са нужни чести закуски, вместо сладки и лепкави храни изберете сирене, кисело мляко или зеленчуци.</p>
<p><img src="/assets/uploads/images/ts79-04-yumusak-fircayla-fircalama.webp" alt="Внимателно четкане с мека четка при чувствителни венци по време на бременност" loading="lazy" /></p>
<h2>Процедури, които могат да се отложат</h2>
<p>Естетични процедури като <a href="/bg/dis-beyazlatma/">избелване на зъби</a>, фасети или корони, незадължителната <a href="/bg/dental-implant-tedavisi/">имплантологична хирургия</a> и обширните естетични обновявания обикновено се планират за след раждането. Това не означава, че тези процедури непременно са вредни; целта е да се избегнат ненужни лекарства и дълги посещения при неспешни процедури.</p>
<p><strong>Какво не бива да се отлага:</strong> силна зъбна болка, оток на лицето, абсцес, температура, травма и фрактура. В тези случаи, независимо от седмицата на бременността, трябва да се потърси помощ без забавяне.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Може ли да ми се направи упойка на зъб по време на бременност?</strong><br>Да. Местните упойки, използвани в денталното лечение, могат да се прилагат при бременност в дози, определени от лекаря. Непременно съобщете за бременността и евентуалното си особено състояние.</p>
<p><strong>Правят ли се дентални рентгенови снимки при бременност?</strong><br>Могат да се правят, ако са необходими за диагнозата. Дозата при денталните снимки е много ниска и те се правят със защитни мерки. Ненужна снимка се отлага.</p>
<p><strong>Венците ми кървят при четкане, нормално ли е?</strong><br>При бременност това е често, но не е състояние, което да се оставя. Продължете внимателното и редовно четкане и почистването между зъбите и си запазете час за преглед; при нужда може да се направи отстраняване на зъбен камък.</p>
<p><strong>Вадят ли се зъби по време на бременност?</strong><br>Ако е необходимо — да. Изваждането на зъб, който причинява инфекция или силна болка, не бива да се отлага. Планирането се прави според седмицата на бременността и общото състояние.</p>
<p><strong>Мога ли да се лекувам по време на кърмене?</strong><br>Да. Местната упойка и обтурациите не са пречка за кърменето. Ако е нужно лекарство, кажете на лекаря, че кърмите.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт планирането на лечението при бъдещи майки се прави чрез съвместна оценка на периода на бременността, находките от клиничния преглед, общото здравословно състояние и препоръките на Вашия акушер-гинеколог. MSc. Dt. Mehmet Taş и неговият екип планират продължителността на часа и положението в стола според седмицата на Вашата бременност.</p>
<p><a href="/bg/agiz-dis-sagligi/">Орално и дентално здраве</a> · <a href="/bg/kanal-tedavisi/">Кореново лечение</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Може ли да се лекуват зъби при бременност, кой период е най-подходящ, защо кървят венците, безопасни ли са упойката и рентгенът? Ръководство за бъдещи майки.',
'Дентално лечение при бременност | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'hamilelikte-dis-tedavisi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Детска дентална медицина: първи преглед, кариес на временните зъби и профилактика',
'<p>Първият дентален преглед на детето се препоръчва в рамките на шест месеца след поникването на първия временен зъб или най-късно на първия рожден ден. Целта на това посещение най-често не е лечение; тя е да се оцени рискът от кариес, на семейството да се даде информация за грижа и хранене според възрастта и детето да свикне с кабинета. При дете, което се е запознало рано, по-късното лечение обикновено се управлява по-лесно.</p>
<p><img src="/assets/uploads/images/ts87-01-ilk-muayene-kucuk-cocuk.webp" alt="Първи преглед на малко дете в денталния стол" loading="lazy"  /></p>
<p>В нашата клиника малките пациенти се оценяват и лекуват от нашия специалист по детска дентална медицина.</p>
<h2>Защо временните зъби са важни?</h2>
<p>Временните зъби не са просто временна редица; те изпълняват функции при дъвченето, развитието на говора и запазването на мястото за постоянните зъби. В празнината от рано загубен временен зъб могат да се преместят съседните зъби и мястото, необходимо за постоянния зъб, да се стесни.</p>
<table>
<thead><tr><th>Функция</th><th>Описание</th></tr></thead>
<tbody>
<tr><td>Дъвчене и хранене</td><td>Болезнен или кариозен зъб може да ограничи дъвченето и разнообразието на храненето на детето.</td></tr>
<tr><td>Развитие на говора</td><td>Предните зъби участват в образуването на някои звуци.</td></tr>
<tr><td>Запазване на мястото</td><td>Всеки временен зъб пази мястото на постоянния зъб под него. При ранна загуба мястото може да се стесни.</td></tr>
<tr><td>Развитие на челюстите</td><td>Балансираното дъвчене подпомага развитието на челюстите и мускулите.</td></tr>
</tbody>
</table>
<h2>Как започва и как се разпознава кариесът на временните зъби?</h2>
<p>Емайлът на временния зъб е по-тънък от този на постоянния; затова <a href="/bg/dis-curugu-kompozit-dolgu/">кариесът</a> при някои деца може да напредва по-бързо. В ранния период може да няма болка, затова редовните прегледи са важни, без да се чака болка.</p>
<ul>
<li>Тебеширеносиви петна близо до ръба на венеца (начален признак)</li>
<li>Кафяво-черна промяна в цвета, вдлъбнатина на повърхността</li>
<li>Чувствителност към студено, топло или сладко</li>
<li>Детето избягва да дъвче от едната страна</li>
<li>Оток на венеца, оток на лицето или температура — в този случай не се чака</li>
</ul>
<p><img src="/assets/uploads/images/ts87-02-sut-disi-curuk-asamalari.webp" alt="Етапи на кариеса на временен зъб от началното петно до напредналия стадий" loading="lazy"  /></p>
<p><strong>Шише и нощно кърмене:</strong> подсладени напитки или сокове от шише по време на сън и честото нощно кърмене се свързват с бързо напредващ кариес на предните зъби. Освен вода не бива да се дават напитки преди и по време на сън.</p>
<h2>Орална хигиена и флуорид според възрастта</h2>
<p>Четкането започва в момента, в който първият зъб се появи в устата. При малките деца четкането се извършва от родителя; в училищна възраст, дори детето да четка само, контролът и подкрепата на родителя продължават.</p>
<table>
<thead><tr><th>Възраст</th><th>Подход</th></tr></thead>
<tbody>
<tr><td>Първи зъб – 3 години</td><td>Два пъти дневно, мека четка с малка глава. Флуоридна паста с размер на оризово зърно (тънка следа). Четкането се прави от родителя.</td></tr>
<tr><td>3 – 6 години</td><td>Два пъти дневно, флуоридна паста с размер на грахово зърно. Детето четка, родителят довършва и контролира. Детето се учи да изплюва пастата, без да изплаква.</td></tr>
<tr><td>6 години и повече</td><td>Четкане два пъти дневно, конец за зъби на контактните повърхности. Родителският контрол продължава, като постепенно намалява.</td></tr>
<tr><td>Всички възрасти</td><td>Тубата с паста се държи извън обсега на детето; пастата не бива да се гълта.</td></tr>
</tbody>
</table>
<p>Подходящото количество паста и нуждата от флуорид се определят от лекаря според възрастта на детето и риска му от кариес.</p>
<p><img src="/assets/uploads/images/ts87-03-yasa-gore-macun-miktari.webp" alt="Количество паста за зъби според възрастта: сравнение между оризово и грахово зърно" loading="lazy"  /></p>
<h2>Профилактични процедури</h2>
<table>
<thead><tr><th>Процедура</th><th>Кога се обсъжда?</th></tr></thead>
<tbody>
<tr><td>Силанти на фисурите</td><td>Когато дълбоките бразди по дъвкателната повърхност на моларите трудно се почистват; прилагат се след поникване на зъба, при липса на кариес.</td></tr>
<tr><td>Флуориден лак</td><td>Може да се прилага в кабинета през определени интервали според оценката на риска от кариес. Честотата не е еднаква при всяко дете.</td></tr>
<tr><td>Консултация за хранене</td><td>Преглеждат се честотата на захарта, режимът на закуски и изборът на напитки.</td></tr>
<tr><td>Обучение по четкане</td><td>Техниката се показва според сръчността и възрастта на детето; определя се ролята на родителя.</td></tr>
</tbody>
</table>
<p>Силантите на фисурите, прилагането на флуорид, задържащите пространство апарати и профилактичните композитни възстановявания се извършват изцяло в нашата клиника.</p>
<p><img src="/assets/uploads/images/ts87-04-fissur-orturucu.webp" alt="Силант, нанесен върху дъвкателната повърхност на молар" loading="lazy"  /></p>
<h2>Загуба на зъб и задържащ пространство апарат</h2>
<p>Ако временен зъб бъде загубен преждевременно поради кариес или травма, може да се обсъди задържащ пространство апарат, за да се ограничи преместването на съседните зъби. Той не е нужен при всяка ранна загуба; решението зависи от това кой зъб е загубен, от възрастта на детето, от етапа на развитие на постоянния зъб под него и от рентгеновите находки.</p>
<h2>Подготовка на детето за часа</h2>
<ul>
<li>Вместо подробни страшни истории преди часа се препоръчва посещението да се представи в спокойна рамка, например като &laquo;броене на зъбките&raquo;.</li>
<li>За запазване на доверието е важно да не се дават категорични обещания от рода на &laquo;няма да боли&raquo; или &laquo;няма да има инжекция&raquo;.</li>
<li>Записването на час във време, когато детето е отпочинало, улеснява сътрудничеството.</li>
<li>Предишни негативни преживявания, евентуални специални нужди и приеманите лекарства трябва да се съобщят преди часа.</li>
</ul>
<p>При деца с изразена тревожност се следва подход на постепенно привикване. При деца, които трудно сътрудничат, при много малки деца или при нужда от обширно лечение то се извършва под седация; седацията се прилага в нашата клиника. В случаите, изискващи обща анестезия, лечението се провежда в нашите партньорски болници в присъствието на анестезиолог и също от специалиста по детска дентална медицина на нашата клиника. Прилаганият метод се решава заедно със семейството след оценка на възрастта на детето, общото му здравословно състояние и обхвата на лечението.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Кога да заведа детето си за първи път при зъболекар?</strong><br>Препоръчва се в рамките на шест месеца след поникването на първия временен зъб, най-късно на първия рожден ден. Дори без оплаквания това посещение служи за оценка на риска от кариес и изготвяне на план за грижа.</p>
<p><strong>Временният зъб така или иначе ще падне, да се лекува ли кариесът му?</strong><br>Да. Нелекуваният кариес може да доведе до болка, инфекция, проблем с храненето и ранна загуба на зъба; ранната загуба може да повлияе върху мястото на постоянния зъб.</p>
<p><strong>Безопасна ли е флуоридната паста за детето?</strong><br>Използвана в подходящо за възрастта количество и под контрол, флуоридната паста се счита за полезна в профилактиката на кариеса. Важно е количеството да отговаря на възрастта и пастата да не се гълта.</p>
<p><strong>Детето ми има разстояния между зъбите, проблем ли е?</strong><br>При временното съзъбие разстоянията най-често са очаквано явление и осигуряват място за постоянните зъби. Оценката все пак се прави при преглед.</p>
<p><strong>Смученето на пръст или биберонът развалят ли зъбите?</strong><br>В зависимост от продължителността и интензивността могат да повлияят на оклузалните отношения. При продължаващ навик се обсъжда подход за отучване, съобразен с възрастта.</p>
<p><strong>Детската дентална медицина и ортодонтията едно и също ли са?</strong><br>Не. Детската дентална медицина обхваща кариеса, профилактичната грижа и лечението на временните зъби; подреждането на зъбите и челюстите е предмет на ортодонтската оценка.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт приоритет при децата е запознаването в период без болка и ранното откриване на риска от кариес. Нуждата от лечение се планира чрез съвместна оценка на клиничния преглед, възрастта на детето, нивото му на сътрудничество и необходимите образни находки.</p>
<p><a href="/bg/agiz-dis-sagligi/">Орално и дентално здраве</a> · <a href="/bg/dis-curugu-kompozit-dolgu/">Кариес и композитна обтурация</a> · <a href="/bg/cocuklarda-dis-travmasi/">Дентални травми при деца</a> · <a href="/bg/kanal-tedavisi/">Кореново лечение</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Кога да се направи първият дентален преглед при децата, защо е важен кариесът на временните зъби, в кои случаи са нужни флуорид и задържащ пространство апарат? Ръководство за семействата.',
'Детска дентална медицина | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'cocuk-dis-hekimligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Дентални травми при деца: първа помощ при счупен или избит зъб',
'<h2>Първите 30 минути: бързо обобщение</h2>
<ol>
<li>Запазете спокойствие, седнете детето и притиснете внимателно кървящото място с чиста марля.</li>
<li>Ако зъбът е изцяло избит, дръжте го за короната (бялата, видима част). Не търкайте корена с ръка, не го четкайте, не го сушете.</li>
<li><strong>Ако е постоянен зъб:</strong> при замърсяване го изплакнете няколко секунди с мляко или физиологичен разтвор; по възможност го върнете в алвеолата. Ако не успеете, съхранявайте го в мляко.</li>
<li><strong>Ако е временен зъб</strong>, не се опитвайте да го поставите обратно. Това може да увреди постоянния зъб под него.</li>
<li>Стигнете до клиниката без забавяне. При избит постоянен зъб първите 30–60 минути са решаващи.</li>
</ol>
<p><strong>Обадете се, преди да тръгнете:</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> — обаждането Ви съкращава времето за подготовка.</p>
<p><img src="/assets/uploads/images/ts88-01-dis-nasil-tutulur.webp" alt="Избит зъб, държан за короната, без да се докосва коренът" loading="lazy"  /></p>
<h2>Временен или постоянен зъб?</h2>
<p>Какво трябва да се направи, зависи изцяло от това разграничение. Първите постоянни резци поникват обикновено между 6- и 8-годишна възраст; при дете под тази възраст падналият преден зъб най-вероятно е временен. При съмнение зъбът не бива да се изхвърля, а да се донесе в клиниката в мляко.</p>
<table>
<thead><tr><th>Ситуация</th><th>Временен зъб</th><th>Постоянен зъб</th></tr></thead>
<tbody>
<tr><td>Изцяло избит</td><td>Не се поставя обратно. Зъбът се донася, детето се преглежда.</td><td>По възможност се връща веднага на мястото; ако не, се донася в мляко.</td></tr>
<tr><td>Счупен</td><td>Донася се отчупеното парче; оценяват се острият ръб и разкриването на пулпата.</td><td>Донася се отчупеното парче; в избрани случаи то може да се залепи обратно.</td></tr>
<tr><td>Изместен</td><td>Оценяват се позицията и съседството с постоянния зъб.</td><td>Може да са нужни репозициониране и шиниране.</td></tr>
<tr><td>Спешност</td><td>Оценка в същия ден</td><td>Минутите са важни</td></tr>
</tbody>
</table>
<p><strong>Защо временният зъб не се поставя обратно?</strong> Коренът на временния зъб е много близо до зародиша на развиващия се под него постоянен зъб. Опитът зъбът да бъде върнат може трайно да повлияе върху развитието и цвета на постоянния зъб.</p>
<p><img src="/assets/uploads/images/ts88-02-sut-disi-daimi-dis-farki.webp" alt="Разрез, показващ разликата в корена и позицията на временния и постоянния зъб" loading="lazy"  /></p>
<h2>Изцяло избит постоянен зъб</h2>
<p>Това е най-чувствителната към времето форма на дентална травма. Запазването на живите клетки по повърхността на корена влияе пряко върху резултата; затова е от основно значение зъбът да не изсъхне.</p>
<h3>Какво трябва да се направи</h3>
<ul>
<li>Зъбът се държи само за короната; повърхността на корена не се докосва.</li>
<li>При видимо замърсяване се изплаква няколко секунди с мляко или физиологичен разтвор. Не се търка, не се използват сапун и дезинфектанти.</li>
<li>По възможност зъбът се поставя внимателно в собствената си алвеола в правилната посока; детето го задържа, като захапе чиста марля.</li>
<li>Ако поставянето не е възможно, зъбът се пренася в мляко. При липса на мляко се използва физиологичен разтвор.</li>
<li>Отива се в клиниката без загуба на време; с предварително обаждане по телефона.</li>
</ul>
<h3>Какво не трябва да се прави</h3>
<ul>
<li>Да се държи зъбът за корена, да се четка, изстъргва или избърсва коренът</li>
<li>Да се поставя зъбът в суха кърпичка, салфетка или джоб</li>
<li>Зъбът да се държи дълго в чешмяна вода</li>
<li>Детето да носи зъба в устата си, ако е в безсъзнание или повръща</li>
</ul>
<table>
<thead><tr><th>Течност за съхранение</th><th>Пригодност</th></tr></thead>
<tbody>
<tr><td>Мляко</td><td>Най-достъпната и подходяща възможност у дома и по пътя</td></tr>
<tr><td>Физиологичен разтвор</td><td>Подходящ; може да се набави от аптека</td></tr>
<tr><td>Собствената слюнка на детето</td><td>Може да се обсъди временно, ако няма друга възможност</td></tr>
<tr><td>Чешмяна вода</td><td>Не е подходяща; уврежда клетките по повърхността на корена</td></tr>
<tr><td>Суха среда (кърпичка, джоб)</td><td>Не е подходяща</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts88-03-saklama-sivisi-sut.webp" alt="Избит зъб, съхраняван в съд с мляко" loading="lazy"  /></p>
<h2>Счупен зъб</h2>
<p>Дълбочината на фрактурата определя лечението. Малка фрактура, засягаща само емайла, не е същото като фрактура с разкриване на пулпата. Ако отчупеното парче бъде намерено, то трябва да се донесе в мляко или физиологичен разтвор; в избрани случаи може да се залепи обратно.</p>
<ul>
<li>Ако върху повърхността на фрактурата се вижда розова или червена точка или има кървене: пулпата може да е разкрита, трябва да се потърси помощ в същия ден.</li>
<li>Ако остър ръб наранява езика или устната, той може временно да се покрие с мек восък или чиста марля.</li>
<li>Дори фрактура да не се вижда, при зъб, получил удар, може да се появи промяна в цвета или забавена болка; нужно е проследяване.</li>
</ul>
<p><img src="/assets/uploads/images/ts88-04-kirik-dis-katmanlari.webp" alt="Разрез на счупен зъб със слоевете емайл, дентин и пулпа" loading="lazy"  /></p>
<h2>Изместен или вклинен зъб</h2>
<p>Зъбът може да смени позицията си, без да излезе изцяло: да се измести напред или назад, да изглежда удължен или да се вклини в костта. В тези случаи не бива да се опитва зъбът да се натиска насила обратно; детето се насочва към мека храна и се довежда в клиниката. Оценката се прави чрез клиничен преглед и необходимите рентгенови снимки.</p>
<h2>Случаи, изискващи незабавно отиване в болница</h2>
<p>При следните находки първо трябва да се отиде в спешно отделение; денталната оценка се прави след това:</p>
<ul>
<li>Загуба на съзнание, сънливост, повтарящо се повръщане, световъртеж</li>
<li>Кървене, което не може да бъде спряно</li>
<li>Изразена деформация на челюстта, невъзможност устата да се отваря и затваря</li>
<li>Кървене от носа или ухото, промяна в зрението</li>
<li>Обширно нараняване на лицето, дълбока рана</li>
<li>Известно нарушение в кръвосъсирването или прием на кръворазреждащи лекарства</li>
</ul>
<p>Начинът на възникване на нараняването (падане, удар, пътнотранспортно произшествие, спорт) и статусът на имунизацията срещу тетанус трябва да се съобщят на лекаря.</p>
<h2>Проследяване след травмата</h2>
<p>Първата помощ при дентална травма е само началото на процеса. При зъб, получил удар, промяна в цвета, мехурче на венеца, болка при захапване или подвижност могат да се появят след седмици, а понякога месеци. Затова зъбите след травма се проследяват клинично и рентгенологично през определени интервали. Неотлагането на контролните часове позволява късно развиващ се проблем да бъде уловен рано.</p>
<p>При деца в растеж възможностите за лечение след травма зависят от етапа на развитие на корена; затова планът се съобразява индивидуално с възрастта на детето и рентгеновите находки. Както спешната помощ, така и дългосрочното проследяване на денталните травми при деца се извършват в нашата клиника от специалиста по детска дентална медицина.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Мога ли сам да върна избития зъб на мястото му?</strong><br>При постоянен зъб, ако детето е спокойно и зъбът не е много замърсен, внимателното му поставяне на мястото е уместно. Временен зъб не се връща. Ако не сте сигурни, поставете зъба в мляко и елате в клиниката без забавяне.</p>
<p><strong>Мога ли да измия зъба с вода?</strong><br>Чешмяната вода не е подходяща. Изплакнете го няколко секунди с мляко или физиологичен разтвор само при видимо замърсяване; никога не търкайте корена.</p>
<p><strong>За колко време трябва да дойда?</strong><br>При избит постоянен зъб първите 30–60 минути са решаващи. Дори това време да е изтекло, зъбът трябва да се донесе, ако е съхраняван в подходяща течност; оценка ще бъде направена така или иначе.</p>
<p><strong>Падна временен зъб, ще поникне нов. Да дойда ли все пак?</strong><br>Да. Трябва да се оцени дали постоянният зъб под него е засегнат и дали има нараняване на венеца и челюстта.</p>
<p><strong>Зъбът потъмня, закъснял ли съм?</strong><br>Промяната в цвета след травма може да се появи след седмици или месеци. Нужна е оценка; не всяка промяна в цвета означава едно и също.</p>
<p><strong>Запазих отчупеното парче, ще послужи ли?</strong><br>В някои случаи отчупеното парче може да се залепи обратно. Донесете го в мляко или физиологичен разтвор, така че да не изсъхне.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт при деца, дошли с дентална травма, приоритет са определянето на обхвата на нараняването и незабавното извършване на чувствителните към времето процедури. Телефонното обаждане преди идване съкращава времето за подготовка.</p>
